css:
*{
  font-family: sans-serif;
  font-size: 15px;
  box-sizing: border-box;
  text-align: justify;
  padding: 0;
  margin: 0;
}

article{
  width: 100%;
  height: 29.7cm;
  padding: 0 .5cm;
  page-break-after: always;
}

@media screen{
    article{
  width: 100%;
  height: 29.7cm;
  padding: 0 1.9cm;
  page-break-after: always;
}
}



.title{
  text-align: center;
  font-size: 20px;
  width: 12cm;
  margin: auto;
  text-decoration: underline;
}

img[alt="meril-logo"]{
  display: block;
  margin-left: auto;
  width: 3cm;
}

p{
  padding-top: 0.4cm;
}

.info:nth-of-type(1){
  margin-top: 0.9cm;
}
.info{
  margin-top: 0.3cm;
}

.print-format{
    margin: 0;
    padding: 0;
}

ol{
    padding-left: 1cm;
}
*::-webkit-scrollbar {
    width: 0 !important;
    height: 0 !important;
}

@page {
        size: A5 portrait;
        margin: 0;
}
